import json, pathlib, re
from build import ROOT, NOTES, render

n = json.loads(NOTES.read_text(encoding='utf8'))

def add(pid, field, text):
    if text not in n[pid].get(field, ''):
        n[pid][field] = n[pid].get(field, '') + '\n\n' + text

def source(pid, url, locator):
    a = n[pid].setdefault('sources', [])
    if not any(x['url'] == url for x in a): a.append(dict(url=url, locator=locator))

def assoc(pid, file, pages, detail):
    a=n[pid].setdefault('associated', [])
    item={'file':file,'pages_read':pages,'scope':detail}
    if item not in a:a.append(item)

# This is a scope closure, not a claim that all source files or all benchmark assets were executed.
